testStubs:
test('calculateDiscount handles zero or negative prices safely', () => {
  const result = calculateDiscount(-5, 0.2);
  expect(result).toBe(0);
});

test('isValidPageIndex rejects out-of-bounds index equal to totalPages', () => {
  const valid = isValidPageIndex(5, 5);
  expect(valid).toBe(false);
});

test('verifyToken rejects expired tokens even with valid signatures', () => {
  const expiredToken = {
    payload: 'user_101',
    expiresAt: Date.now() - 3600000,
    signature: computeExpectedSignature('user_101'),
  };
  const isValid = verifyToken(expiredToken);
  expect(isValid).toBe(false);
});

test('authorize enforces strict conjunction of all required permissions', () => {
  const validToken = {
    payload: 'user_202',
    expiresAt: Date.now() + 3600000,
    signature: computeExpectedSignature('user_202'),
  };
  const request = {
    headers: { 'authorization-token': validToken },
    user: { role: 'member', permissions: ['read'] },
  };
  const result = authorize(request, ['read', 'write']);
  expect(result.authorized).toBe(false);
});
